(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["es"] = {"ui":{"lead":"La gente no solo ha jugado a los juegos: también los ha pintado. Amplía 3300 años de pinturas y figuras y mira los detalles.","details":"Detalles","links":"Ver o jugar el juego","record":"Sobre la obra","game":"Juego","exhibit":"Colección","room":"Sala","room_chance":"Azar","hint":"Pellizca o usa la rueda para ampliar · arrastra para mover · toca un número","r_artist":"Autor","r_date":"Fecha","r_place":"Lugar","r_medium":"Técnica","r_size":"Tamaño","r_museum":"Museo","r_credit":"Procedencia","r_rights":"Imagen","met":"The Metropolitan Museum of Art","cc0":"Acceso abierto (dominio público)","metlink":"La obra en la web del museo","credit":"Imágenes: The Metropolitan Museum of Art, The Cleveland Museum of Art, The Art Institute of Chicago y el Rijksmuseum, acceso abierto (dominio público).","cma":"The Cleveland Museum of Art","aic":"The Art Institute of Chicago","rijks":"Rijksmuseum, Ámsterdam"},"nefertari":{"title":"La reina Nefertari jugando al senet","artist":"Nina de Garis Davies (facsímil)","date":"original h. 1290–1224 a. C. · facsímil 1921–22","place":"Egipto (Valle de las Reinas)","game":"Senet","medium":"Témpera sobre papel (facsímil a la mitad del tamaño)","p":["Nefertari fue la esposa principal de Ramsés II. Es una copia de una pintura de su tumba en el Valle de las Reinas, hecha dentro de la tumba en 1921–22; se copiaron incluso las grietas y las faltas del muro.","La reina, sentada ante un tablero, juega al senet contra un rival invisible. Pintado en una tumba, se cree que el juego significaba algo más que diversión: ganar el viaje hacia el más allá."],"spots":[["Dos clases de piezas","Sobre el tablero hay piezas puntiagudas y piezas en forma de carrete: una para cada jugador."],["La mano de la reina","Sus dedos van a tomar una pieza."],["Tablero y soporte","El tablero se ve de lado, por eso no se ven las casillas. Descansa sobre un soporte de patas finas."],["Su nombre","El nombre de la reina está escrito dentro de un óvalo, un cartucho."],["El rival invisible","Enfrente no hay nadie: la reina juega contra un rival que no se ve."]]},"hydria":{"title":"Aquiles y Áyax jugando a un juego de tablero (hidria)","artist":"Atribuida al Grupo de Leagros","date":"h. 510 a. C.","place":"Grecia (Ática)","game":"Un juego de dados","medium":"Terracota (figuras negras)","p":["Durante el asedio de Troya, dos héroes griegos, Aquiles y Áyax, matan el tiempo ante un tablero. La escena la inventó hacia 540 a. C. el alfarero y pintor Exequias; su original se conserva en un ánfora de los Museos Vaticanos.","El tema gustó muchísimo entre 540 y 480 a. C., y se conocen más de 150 ejemplos. En esta hidria, la diosa Atenea está en el centro. Los héroes juegan a un juego en el que las piezas avanzan según la tirada de los dados."],"spots":[["Atenea","La diosa Atenea está de pie entre los dos."],["El héroe de la izquierda","Todavía con la lanza en la mano, se inclina sobre el tablero."],["El héroe de la derecha","Tampoco ha dejado las armas: un rato de juego en plena guerra."],["El tablero","El bloque bajo entre ambos es el tablero."],["El hombro","En el hombro de la vasija parte un carro."]]},"liubo":{"title":"Pareja de figuras sentadas jugando al liubo","date":"siglo I a. C. – siglo I d. C.","place":"China (dinastía Han)","game":"Liubo","medium":"Loza con pigmento","p":["Dos jugadores de liubo, la gran afición de la China Han. Figuras así se ponían en las tumbas con el deseo de que los placeres de la vida siguieran tras la muerte.","En la foto, entre ellos están el tablero de liubo y las piezas de hueso de la colección de este museo. Las figuras captan un momento dramático de una partida reñida."],"spots":[["El tablero de liubo","Es el mismo tablero que «Tablero y piezas de liubo» de la colección: mira las marcas en T, L y V."],["El jugador de la izquierda","Estudia el tablero con calma."],["El jugador de la derecha","Mano en alto y boca muy abierta: ¿acaba de hacer una jugada ganadora?"],["Piezas en el tablero","Las piezas de hueso están a ambos lados del tablero."],["Piezas fuera del tablero","Hay más piezas en el suelo."]]},"shahnama":{"title":"«Buzurjmihr descifra el juego indio del ajedrez», del Shahnama del sah Tahmasp","artist":"Pintura atribuida a ʿAbd al-Vahhab","date":"h. 1530–35","place":"Irán (Tabriz)","game":"Ajedrez","medium":"Acuarela opaca, tinta, plata y oro sobre papel","p":["Una escena del poema épico de Ferdousí, el Shahnama (Libro de los reyes). El rey de la India envía un emisario con un tablero y piezas de ajedrez y desafía al rey persa Nushirvan: si descubre cómo se juega, la India pagará tributo.","Solo el joven sabio Buzurjmihr lo resuelve a tiempo. En el Shahnama, Persia envía después el backgammon a cambio, y los indios no logran resolverlo. El rey y los cortesanos miran fijamente el tablero y a los jugadores."],"spots":[["El tablero","Las piezas están sobre un tablero cuadriculado, tan pequeñas que cuesta distinguir sus formas."],["El rey Nushirvan","En su trono, espera a ver resuelto el enigma."],["Alrededor del tablero","Los jugadores se inclinan sobre el tablero."],["Los versos","Los recuadros de arriba y abajo llevan versos de Ferdousí."],["Los cortesanos","Hombres con turbantes de altas varillas rojas miran de pie."]]},"chaupar":{"title":"Shiva y Parvati jugando al chaupar, de una serie del Rasamanjari","artist":"Devidasa de Nurpur","date":"1694–95","place":"India (Basohli, Jammu)","game":"Chaupar (pariente del antepasado del Ludo)","medium":"Acuarela opaca, tinta, plata y oro sobre papel","p":["Una página de una serie que ilustra el Rasamanjari, un poema amoroso sánscrito del siglo XV. El dios Shiva y su esposa Parvati se sientan sobre una piel de tigre ante un tablero en forma de cruz.","Shiva acaba de quitarle a Parvati un collar con trampas, y ella le suplica. Color atrevido, una profundidad espacial ambigua, y el color y el gesto usados por su significado: son los rasgos de la escuela de Basohli."],"spots":[["El tablero en cruz","El chaupar y el pachisi se juegan en un tablero con esta forma de cruz."],["Barras blancas en el tablero","Probablemente los dados largos (pasa) del chaupar."],["Shiva","De cuerpo blanco, con una serpiente al cuello."],["Parvati","Con la mano tendida, pide que le devuelva el collar."],["La piel de tigre","Los dos están sentados sobre una piel de tigre."]]},"shogi":{"title":"Una joven y un joven jugando al shōgi («Chūnagon Kanesuke», de los Treinta y Seis Inmortales de la Poesía)","artist":"Suzuki Harunobu","date":"h. 1767–69","place":"Japón (Edo)","game":"Shogi","medium":"Xilografía (nishiki-e)","p":["Una estampa de una serie que alude a los Treinta y Seis Inmortales de la Poesía; esta representa al poeta Chūnagon Kanesuke. Una noche de verano, junto a una mosquitera, una joven y un joven juegan al shogi.","Harunobu fue el artista que popularizó las estampas a todo color, impresas con muchas planchas. Hasta las piezas del tablero están dibujadas con detalle."],"spots":[["Un tablero de shogi con patas","Un tablero grueso con patas, como los de hoy."],["Una cajita","Probablemente la caja de las piezas."],["La mosquitera","Cuelga una mosquitera verde: es una noche de verano."],["El farol","Una lámpara de pie ilumina el tablero."],["El poema","El recuadro en forma de nube lleva el nombre del poeta y un poema."]]},"sugoroku":{"title":"Dos jóvenes jugando al sugoroku","artist":"Utagawa Toyokuni I","date":"periodo Edo (finales del s. XVIII – inicios del s. XIX)","place":"Japón (Edo)","game":"Ban-sugoroku (pariente del backgammon)","medium":"Díptico de xilografías","p":["Dos estampas unidas en una imagen ancha: unas jóvenes reunidas en una sala disfrutan de una partida de ban-sugoroku. El juego es pariente del backgammon, de la misma línea que el tablero de sugoroku del Shōsōin de esta colección.","Sobre el tablero hay piedras blancas y negras, y la joven de la derecha sostiene un cubilete para agitar los dados. Por la ventana se ve el monte Fuji."],"spots":[["El tablero","Piedras blancas y negras sobre sus casillas alargadas."],["El cubilete","En él se agitan los dados."],["Piedras fuera del tablero","¿Ya sacadas, o aún sin entrar?"],["El monte Fuji","El Fuji tras la ventana."],["La unión","Aquí se juntan las dos estampas."]]},"eakins":{"title":"Los jugadores de ajedrez","artist":"Thomas Eakins","date":"1876","place":"Estados Unidos (Filadelfia)","game":"Ajedrez","medium":"Óleo sobre tabla","p":["En el salón de una casa de Filadelfia, dos amigos juegan al ajedrez mientras el padre del artista, Benjamin Eakins, mira. Eakins aprendió su cuidadosa construcción del espacio y su detalle preciso de su maestro en París, Gérôme.","En 1881, Los jugadores de ajedrez fue la primera obra que el Metropolitan aceptó como donación de un artista vivo."],"spots":[["Las piezas","En la sala en penumbra, las piezas del tablero destacan con la luz."],["El padre del artista","De pie, mirando la partida: Benjamin Eakins."],["El jugador de la derecha","El pintor George W. Holmes, amigo del padre del artista."],["El cajón","Una inscripción latina: «El hijo de Benjamin Eakins pintó esto en el 76»."],["Sobre la chimenea","Una reproducción de un cuadro de Gérôme, el maestro de Eakins."],["El gato","En el suelo, solo el gato parece no interesarse por la partida."]]},"weiqi":{"title":"Plato con inmortales jugando al weiqi","artist":"Anónimo","date":"1425–36 (dinastía Ming, periodo Xuande)","place":"China","game":"Go (weiqi)","medium":"Laca tallada roja y verde","size":"Alt. 3,5; anch. 14,9; long. 23,5 cm","credit":"Donación de Florence y Herbert Irving, 2015","p":["Un plato de laca tallada: se aplicaron decenas de capas y luego se tallaron; bajo la roja hay una capa verde, y la profundidad del corte hace aparecer los colores. Dentro del borde lobulado, unos inmortales juegan al go bajo un pino.","En China existe la leyenda de Lanke, el «mango de hacha podrido»: el leñador Wang Zhi observó a unos inmortales jugar al go en la montaña y, al volver en sí, había pasado tanto tiempo que el mango de su hacha se había podrido. Los inmortales ante el tablero eran un tema muy querido. Quién es la figura de pie, los registros no lo dicen."],"spots":[["El tablero","El tablero de go entre los dos inmortales, tallado hasta en sus líneas."],["Los inmortales jugando","Dos figuras sentadas junto a las rocas, en torno al tablero."],["La figura de pie","Una figura de pie algo apartada. Recuerda al leñador de la leyenda, pero no se sabe quién es."],["La luna","Una luna redonda en el cielo (o quizá el sol)."],["El pino","Un pino de ramas extendidas, árbol que suele evocar la longevidad y la tierra de los inmortales."],["El borde de peonías","Grandes peonías y hojas talladas alrededor del borde."]]},"webb":{"title":"Los jugadores de backgammon (armario)","artist":"Philip Webb (diseño), Edward Burne-Jones (pintura), Morris, Marshall, Faulkner & Co. (fabricación)","date":"1861","place":"Gran Bretaña (Londres)","game":"Backgammon","medium":"Pino pintado, óleo sobre cuero, latón, cobre","size":"Alt. 185,4; anch. 114,3; prof. 53,3 cm","credit":"Rogers Fund, 1926","p":["Uno de los primeros muebles de la empresa que William Morris fundó con unos amigos en 1861. Sobre el cuero de las puertas, un hombre y una mujer vestidos a la medieval juegan al backgammon, pintados al óleo. Se expuso en la Exposición Internacional de Londres de 1862.","Resume el propósito de Arts and Crafts de borrar la frontera entre las bellas artes y las artes aplicadas. El fondo de cuero está punteado con diminutos golpes, una técnica medieval."],"spots":[["El tablero","El tablero de backgammon sobre la mesa, entre los dos."],["El hombre","Un joven, con una ficha en la mano, estudia el tablero."],["La mujer","Frente a él, una mujer con una ficha (o un cubilete)."],["Flores a sus pies","A los pies de los jugadores crecen flores."],["Cuero punteado","El fondo de cuero está punteado con finos golpes que atrapan la luz."],["Bandas de rombos","Bandas de rombos sobre oro enmarcan las puertas arriba y abajo."]]},"liberale":{"title":"Los jugadores de ajedrez","artist":"Liberale da Verona","date":"h. 1475","place":"Italia (Verona)","game":"Ajedrez","medium":"Temple sobre tabla","size":"34,9 × 41,3 cm","credit":"Colección Maitland F. Griggs, legado de Maitland F. Griggs, 1943","p":["Fragmento del frente de un cassone, el arcón decorado que guardaba el ajuar de una novia en la Italia del Renacimiento. Liberale fue conocido también por iluminar los cantorales de la catedral de Siena.","Muestra un momento de una historia de amor no identificada. En el fragmento compañero, una doncella en una ventana parece invitar a un joven a entrar; aquí los dos juegan al ajedrez. Según el museo, ella está a punto de perder. El ajedrez era una imagen favorita del cortejo en la literatura amorosa de la época."],"spots":[["El tablero","Un tablero rojo y blanco con piezas oscuras; la partida parece cerca del final."],["El joven","Alarga la mano hacia el tablero y parece a punto de ganar."],["La doncella","Sentada enfrente; en el panel compañero lo llama desde una ventana."],["La ventana","Tras la ventana abierta, una colina y el cielo."],["Jóvenes mirando","Hombres de brazos cruzados siguen la partida."],["Damas mirando","Mujeres que observan la partida tras la columna."]]},"mirror":{"title":"Estuche de espejo con una pareja jugando al ajedrez","artist":"Anónimo","date":"1325-1350","place":"Francia (París)","game":"Ajedrez","medium":"Marfil","size":"Diámetro 10,2 cm","credit":"Compra con el Fondo J. H. Wade, 1940","p":["Este disco de marfil del tamaño de la palma de la mano cubría un espejo de mano. En el París del siglo XIV, un espejo de metal pulido se guardaba entre dos placas de marfil y se llevaba encima; marfiles tallados como este eran lujos apreciados por cortesanos y aristócratas.","Dentro de una tienda con cortinas, un joven y una dama juegan al ajedrez. En los relatos medievales, el ajedrez representaba a la vez el amor y la guerra. Se ha propuesto que la pareja sea Tristán e Isolda, o Lanzarote y Ginebra, pero nadie lo sabe. El museo pregunta a sus visitantes: ¿quién crees que va ganando?"],"spots":[["El tablero","Un tablero sobre una mesa de un solo pie, con algunas piezas."],["El joven","Alarga la mano para hacer su siguiente jugada."],["La dama","Una mujer con toca; la punta de sus dedos toca una pieza."],["La mano cerrada","Su otra mano, cerrada, descansa en el regazo. ¿Guarda una pieza que ha capturado?"],["La tienda","Cortinas recogidas a ambos lados, escenario frecuente del ajedrez en los estuches de espejo."]]},"morris":{"title":"Un tablero de juego (el molino)","artist":"Peter Flötner","date":"1500-1546","place":"Alemania","game":"Molino (Nine Men’s Morris)","medium":"Xilografía","credit":"Fondo de Dotación Charles W. Harkness, 1923","p":["Una xilografía de Peter Flötner, uno de los escultores más dotados del Núremberg renacentista, que también diseñó ornamentos, muebles, modelos para orfebres y una baraja famosa por su sátira. Bajo el follaje en espiral se esconde el tablero del molino («Mühle» en alemán): tres cuadrados uno dentro de otro, unidos por el centro de cada lado.","El tablero tiene 24 puntos. Quien alinea tres piezas propias (un molino) retira una del rival. Grabados así servían también de modelo a los artesanos, y el museo expuso esta hoja en una muestra de modelos y diseños de orfebres. No consta si se jugaba sobre el papel o si se copiaba en madera o metal."],"spots":[["El cuadrado central","El cuadrado más interior, cubierto de fino entrelazado."],["Una esquina exterior","Esquina del cuadrado exterior: uno de los 24 puntos donde se colocan las piezas."],["Una esquina intermedia","Las esquinas del cuadrado del medio también son puntos."],["Las líneas de unión","Bandas que unen los tres cuadrados por el centro de cada lado; las piezas también se mueven por ellas."],["Un mascarón","Cartelas en espiral con rostros arriba, abajo y a los lados: ornamento de grutesco renacentista."],["La orla de vid","Hojas y frutos tallados en blanco sobre fondo negro."]]},"leifeng":{"title":"Juego de tablero de la pagoda Leifeng","artist":"Anónimo","date":"1736-1795 (periodo Qianlong)","place":"China","game":"Juego de carrera","medium":"Xilografía; tinta sobre papel","size":"31 × 29,8 cm","credit":"Compra con el Fondo J. H. Wade, 2025","p":["Una hoja impresa para jugar, del reinado del emperador Qianlong de la China Qing. Sus casillas reúnen a los personajes de la Leyenda de la Serpiente Blanca: el espíritu serpiente Bai Suzhen («la Dama Blanca»), su compañera Xiaoqing («la Pequeña Verde»), el joven Xu Xuan (Xu Xian en versiones posteriores) y el monje Fahai, que al final encierra a la Dama Blanca bajo la pagoda Leifeng, junto al Lago del Oeste.","El recorrido gira en espiral desde una casilla marcada 起馬, «salida», hasta la pagoda del centro. Probablemente se corría por la historia con dados, como en el juego de la oca occidental; las reglas no se conservan. Según el museo, estas estampas en color se vendían en las ciudades y se colgaban en las paredes como parte de la cultura visual urbana, cada color impreso con su propia plancha tallada."],"spots":[["Salida","La casilla marcada 起馬, «salida»: probablemente el punto de partida."],["La Dama Blanca y la Pequeña Verde","El espíritu serpiente Bai Suzhen y su compañera Xiaoqing."],["Xu Xuan","El joven que se casa con la Dama Blanca."],["El monje Fahai","El monje que la encierra bajo la pagoda."],["La pagoda Leifeng","La pagoda junto al Lago del Oeste de Hangzhou, donde termina la historia."],["El centro","Una mujer sentada ante la pagoda y un hombre arrodillado: la última escena del relato y, quizá, la meta."]]},"tutinama":{"title":"El mono herido muerde la mano del príncipe, su compañero de ajedrez (del Tuti-nama, Cuentos de un loro)","artist":"Dasavanta","date":"h. 1560","place":"India (corte mogol de Akbar)","game":"Ajedrez","medium":"Témpera, tinta y oro sobre papel","size":"20 × 14,2 cm (pintura 10,2 × 10,6 cm)","credit":"Donación de la Sra. A. Dean Perry, 1962","p":["Una ilustración del Tuti-nama, los «Cuentos de un loro», hecho en la corte del emperador mogol Akbar. Es uno de los relatos con que una madre loro advierte a sus polluelos contra las amistades con otras especies, como los cachorros de zorro. En él, un mono que jugaba bien al ajedrez solía jugar con un príncipe.","Un día, delante de unos invitados, el mono hizo una broma grosera y el príncipe le dio una bofetada; el mono le mordió la mano. Fuera, a la derecha, los criados preparan la comida mientras los invitados miran asombrados. Una inscripción abajo nombra a Dasavanta, que llegaría a ser uno de los maestros más célebres de la corte mogol; de joven puso una capa de azul frío bajo su pintura."],"spots":[["El mono","Muerde la mano del príncipe, su compañero de ajedrez."],["El príncipe","El príncipe mordido."],["El tablero","Un tablero de casillas rojas en el suelo."],["Los invitados asombrados","Los invitados a la reunión."],["La comida","Criados que ponen ollas al fuego afuera."],["El texto persa","Arriba, la historia escrita en persa."]]},"teniers":{"title":"Partida de backgammon","artist":"David Teniers","date":"década de 1640","place":"Flandes","game":"Backgammon","medium":"Óleo sobre tabla, pasado a lienzo","size":"59 × 80,6 cm","credit":"Donación del Sr. y la Sra. Samuel D. Wise, 1943","p":["Una partida de backgammon con mucho en juego, pintada por el flamenco Teniers. El juego es muy antiguo: su forma moderna apareció en el siglo XV, y el nombre «backgammon» nació más o menos cuando se pintó este cuadro. En el siglo XVII era popularísimo y se jugaba a menudo por dinero.","Los mirones rodean a los dos jugadores, y junto a la pared alguien lleva la cuenta. Por las mujeres que miran —una se asoma a una ventana— el museo cree que la sala es el cuarto de juego de un burdel. Estas escenas solían llevar una moraleja: el juego de azar era necio, incluso perverso, y una pérdida de tiempo."],"spots":[["El tablero","Un tablero de backgammon abierto sobre la mesa, con la partida en marcha."],["El hombre de blanco","Un jugador de espaldas, alargando la mano hacia sus fichas."],["El hombre con la mano en la mejilla","Su rival, absorto."],["El tanteador","Un hombre marca una tabla en la pared: ¿los puntos o las apuestas?"],["La mujer en la ventana","Una mujer mayor que mira desde arriba."],["La sala del fondo","Al fondo, hombres beben junto a una joven."]]},"imari":{"title":"Plato con dos hombres jugando al go","artist":"Anónimo","date":"siglo XVIII","place":"Japón (periodo Edo)","game":"Go","medium":"Porcelana moldeada con esmaltes sobre cubierta (Hizen, estilo Imari)","size":"2,4 × 13,8 cm","credit":"Colección Severance y Greta Millikin, 1964","p":["En este pequeño plato cuadrado, dos hombres juegan al go bajo un pino: el de amarillo, sentado frente al tablero puesto en el suelo; su rival de verde, recostado en el árbol.","Es porcelana de Imari hecha en Hizen (hoy Saga y Nagasaki), y sus verdes recuerdan los esmaltes de Kutani. Se hizo para la exportación, cuando Japón ya había sustituido a China como principal proveedor de porcelana de Europa."],"spots":[["El tablero de go","Un tablero cuadriculado, puesto directamente en el suelo."],["El hombre de amarillo","Sentado frente al tablero."],["El hombre de verde","Su rival, recostado en el árbol y sonriendo."],["El pino","Un pino extiende sus ramas por encima."],["El marco rojo","Un marco rojo de esquinas cortadas rodea la escena."]]},"shoei":{"title":"Las cuatro artes (uno de un par de biombos)","artist":"atribuido a Kanō Shōei","date":"finales del siglo XVI–principios del XVII","place":"Japón (periodo Momoyama)","game":"Go","medium":"Uno de un par de biombos de seis hojas; tinta y color ligero sobre papel","size":"153 × 358,6 cm","credit":"Fondo John L. Severance, 1979","p":["Un biombo de seis hojas atribuido a Kanō Shōei, de la escuela Kanō. Con su pareja muestra las «cuatro artes» que se esperaban de un caballero culto chino: tocar el qin, jugar al qi (go), la caligrafía y la pintura. Aquí, caballeros chinos de alto rango y sus criados descansan en el campo bajo los pinos.","En el centro, dos hombres juegan al go mientras un tercero observa. Cerca, una mesa sostiene libros y un qin aún en su funda de tela, esperando a que lo toquen. La escena equilibra disfrute y formalidad. El museo señala que uno de los criados se distrae con el movimiento de un pez en el agua."],"spots":[["El tablero de go","Un tablero con patas; dos caballeros juegan frente a frente."],["Los caballeros","Dos jugadores y un tercero que mira."],["La mesa","Probablemente la mesa con los libros y el qin en su funda."],["Los criados","Sirvientes que esperan junto a la mesa."],["El criado distraído","Tumbado junto al agua, mira moverse un pez."],["El pino","Un gran pino extiende sus ramas sobre la escena."]]},"umaya":{"title":"Biombo de las caballerizas (go y shogi en la galería)","artist":"Anónimo","date":"Principios del siglo XVI","place":"Japón (periodo Muromachi)","game":"Go y shogi","medium":"Uno de una pareja de biombos de seis hojas; tinta, color y oro sobre papel","size":"146,1 × 346,6 cm","credit":"Edward L. Whittemore Fund, 1934","p":["Este biombo de seis hojas unidas es uno de una pareja. Los preciados caballos de las cuadras quizá sean el tema principal, pero en la galería de delante ocurren muchas cosas.","Allí la gente se desafía en dos juegos distintos: go a la izquierda y shogi a la derecha. Según el museo, el ambiente animado nace del contraste entre los caballos inquietos y la estrategia serena de los juegos. En Japón se creía que los monos protegían a los caballos, y a veces se tenían en las cuadras."],"spots":[["El tablero de go","Un tablero de líneas finas con piedras negras."],["Dos hombres con gorro negro","Hombres con alto eboshi negro: el de verde tiende la mano al tablero, el de rojo mira."],["El tablero de shogi","Un tablero de casillas grandes, muchas menos que en el de go."],["El rival que ríe","Un monje rapado coge una pieza mientras el hombre de enfrente se lleva la mano a la cabeza y ríe a carcajadas. ¿Alguien acaba de anotarse un tanto?"],["Un mono","Al final de la galería, ¿un mono con chaqueta roja?"],["Un caballo","Un caballo negro se encabrita, sujeto por sus cuerdas."]]},"goryeo":{"title":"Jarra con figuras jugando al go, de celadón con incrustaciones","artist":"Anónimo","date":"Siglo XIII","place":"Corea (dinastía Goryeo)","game":"Go (baduk)","medium":"Celadón con incrustaciones de engobe blanco y negro","size":"Alt. 20,4 cm, diám. 14,3 cm","credit":"Donación de John L. Severance, 1917","p":["Una jarra de celadón de Goryeo, con pico y asa. La incrustación —grabar líneas en el barro, rellenarlas de engobe blanco y negro y luego vidriar y cocer— era la especialidad de los alfareros de Goryeo; aquí, dentro de un marco redondo, dos figuras sentadas bajo un sauce resaltan en blanco.","Entre ellas hay un tablero, y el museo compara la escena con las imágenes de partidas de go —baduk en coreano—. Tocar la cítara, el go, la caligrafía y la pintura eran las «cuatro artes» del letrado culto, y sus elegantes reuniones se convirtieron también en motivos para los artesanos. El celadón coreano con figuras humanas es poco común."],"spots":[["El tablero","El tablero entre los dos, un cuadrado blanco."],["La figura de la izquierda","Sentada frente al tablero."],["La figura de la derecha","El rival, sentado enfrente."],["El sauce","Ramas de sauce cuelgan sobre ellos, dibujadas con engobe negro."],["El marco de nubes","Volutas como nubes rodean el marco redondo."],["El craquelado","Finas grietas en el vidriado. Se forman al enfriarse, porque el barro y el vidriado encogen de forma distinta."]]},"kangra":{"title":"Pareja jugando al chaupar en una terraza","artist":"Anónimo","date":"h. 1790–1800","place":"India (Pahari, escuela de Kangra)","game":"Chaupar","medium":"Dibujo con boceto previo en ocre rojo","size":"19,4 × 13,2 cm","credit":"Edward L. Whittemore Fund, 1936","p":["Dibujo de un artista de Kangra, en las colinas pahari al pie del Himalaya. El primer boceto se hizo en rojo (ocre rojo) y luego se precisó en negro. Sin color encima, se puede seguir cada línea de las figuras y sus objetos.","Un hombre y una mujer, sentados en una terraza a ambos lados de un tablero en cruz, juegan al chaupar, un antiguo juego de carreras indio sobre la misma cruz que el parchís (pachisi), que se mueve lanzando dados largos (pasa). Las casillas aún no están dibujadas en el tablero. Unas sirvientas atienden a la pareja."],"spots":[["El tablero en cruz","Un tablero en forma de cruz, en el suelo. Sus casillas aún no están dibujadas."],["La mujer","Con la palma hacia arriba: ¿a punto de lanzar los dados?"],["El hombre","Turbante con penacho; tiende la mano hacia el tablero."],["La sirvienta de la izquierda","Sostiene un frasquito y extiende un paño."],["La sirvienta de la derecha","Sostiene un utensilio de mango largo y un recipiente pequeño."],["El boceto rojo","Alrededor del turbante, el boceto rojo asoma bajo las líneas negras."]]},"vuillard":{"title":"La partida de damas (de Paisajes e interiores)","artist":"Édouard Vuillard","date":"1899","place":"Francia","game":"Damas","medium":"Litografía en color (estado III/III); impresa por Auguste Clot, editada por Ambroise Vollard","size":"Imagen 33 × 25,7 cm (hoja 38 × 30,8 cm)","credit":"Donación del Hanna Fund, 1951","p":["Ambroise Vollard, marchante de pintura impresionista, fue también un importante editor de grabados. En 1895 encargó a Pierre Bonnard un álbum de 12 litografías en color y después publicó muchos más, entre ellos Paisajes e interiores de Vuillard, impreso por el maestro impresor Auguste Clot.","Bonnard y Vuillard formaban parte de los nabis —«profetas» en hebreo—, que buscaban un arte nuevo en el que la forma y el color expresaran por sí mismos el sentimiento, y que amaban las escenas de la vida urbana y familiar. En una habitación llena de motivos, dos hombres se enfrentan ante un tablero de damas mientras una mujer, de pie, observa. En francés el juego se llama «dames»; la nota a lápiz abajo a la izquierda dice «partie de dames», una partida de damas."],"spots":[["El tablero","Un pequeño tablero a cuadros, con las piezas colocadas."],["El hombre de la izquierda","Un hombre con barba extiende la mano sobre el tablero."],["El hombre de la derecha","Su rival, inclinado sobre el tablero en un sillón, medio oculto por la mujer de pie."],["La mujer de pie","Con la mano en la barbilla, sigue la partida."],["La lámpara","Una lámpara junto a la pared. El papel pintado y la tapicería están llenos de motivos."],["La nota a lápiz","Abajo a la izquierda, a lápiz: «partie de dames», una partida de damas."]]},"talbot":{"title":"Los jugadores de ajedrez (fotografía temprana)","artist":"Atribuida a William Henry Fox Talbot","date":"h. 1843–47","place":"Inglaterra","game":"Ajedrez","medium":"Copia a la sal","size":"19,9 × 15 cm","credit":"Adquirida con fondos del Sr. y la Sra. Everett Kovler","p":["El procedimiento negativo-positivo inventado por Talbot, con las copias ilimitadas que hizo posibles, dominó la fotografía hasta la era digital. Sus primeros experimentos muestran a la vez su interés científico y su ambición artística, y los estudiosos han confirmado que tomó diez o más vistas de jugadores de ajedrez.","Sin embargo, esta quizá no sea suya: esta copia y otras de la misma escena no están firmadas y usan un papel distinto del habitual de Talbot. Los retratados serían el fotógrafo Antoine Claudet y el ayudante de Talbot, Nicolaas Henneman; estudios recientes sugieren que las imágenes se hicieron en el estudio de Claudet, pasaron a Henneman y llegaron a Talbot como parte del pago de una deuda (nota del museo)."],"spots":[["El tablero","El tablero sobre la mesa, con las piezas en fila."],["El hombre de chistera","Sin quitarse el sombrero, toma una pieza."],["El pensativo","Con la mano en la barbilla, el rival estudia el tablero."],["La cortina","Una cortina al fondo: ¿un decorado para la toma?"],["Otro sombrero","Otra chistera descansa sobre el soporte de la derecha."]]},"pvl":{"title":"Hombres jugando a los dados","artist":"Maestro PVL","date":"h. 1520","place":"Países Bajos","game":"Dados","medium":"Grabado a buril sobre papel","size":"9,4 × 9,4 cm (circular)","credit":"Colección Charles Hack y Hearn Family Trust, adquirida en 2023","p":["Obra de un grabador anónimo activo en los Países Bajos a principios del siglo XVI, llamado Maestro PVL por el monograma «PVL» grabado abajo a la izquierda. En un grabado redondo que cabe en la palma de la mano, finísimas líneas apretadas construyen la profundidad de la sala y la textura de la ropa.","Sobre la mesa hay dos dados. Un hombre inclinado y un joven con cuello de piel señalan y discuten, quizá por la cuenta. Detrás miran unas mujeres, y bajo la mesa hay una jarra de vino. Los dados van unidos al juego de apuestas desde la Antigüedad y fueron prohibidos una y otra vez."],"spots":[["Los dados","Dos dados rodando sobre la mesa."],["Las manos que señalan","Dos dedos se encuentran sobre la mesa: ¿una disputa por la cuenta?"],["El hombre del sombrero ancho","Inclinado hacia delante; sus mangas acuchilladas y abullonadas eran la moda de la época."],["El joven del cuello de piel","Un joven con gran sombrero y cuello de piel."],["Las mujeres que miran","Unas mujeres observan la partida desde atrás."],["El monograma","«PVL» abajo a la izquierda: la única pista del nombre del artista."]]},"kiyohiro":{"title":"Jugadoras de sugoroku","artist":"Torii Kiyohiro","date":"h. 1750","place":"Japón (periodo Edo)","game":"Ban-sugoroku","medium":"Xilografía en color (benizuri-e), ōban; editor Urokogataya","size":"43,5 × 29,3 cm","credit":"Colección Clarence Buckingham","p":["Torii Kiyohiro fue un artista de ukiyo-e activo entre hacia 1737 y 1776. Esta es una benizuri-e, impresa con pocas planchas de color —rosa beni, verde y similares— en los años anteriores a la aparición, en 1765, de las nishiki-e a todo color.","El juego sobre el soporte negro es el ban-sugoroku: dos jugadores tiran los dados y mueven fichas blancas y negras, y gana quien saque antes todas las suyas. Es de la misma familia que el backgammon, y los grabados ukiyo-e muestran a menudo a mujeres disfrutándolo. Detrás, una mujer fuma una pipa larga y mira."],"spots":[["El tablero","Un tablero de sugoroku sobre su soporte, con fichas blancas y negras."],["La figura de la izquierda","Alarga la mano para mover una ficha."],["La mujer de la derecha","Inclinada sobre el tablero, la rival estudia las fichas."],["La mujer de la pipa","Con una larga pipa kiseru, sigue la partida desde atrás."],["La mano alzada","La mujer de la derecha sostiene algo pequeño y negro: ¿el cubilete?"],["La firma","«Torii Kiyohiro hitsu», con el sello del editor Urokogataya."]]},"ingram":{"title":"El juego del ajedrez chino","artist":"John Ingram, según François Boucher","date":"1741–63","place":"Francia (París)","game":"Xiangqi","medium":"Aguafuerte y buril","size":"Hoja 39,4 × 27,7 cm (plancha 24,5 × 16,4 cm)","credit":"Colección Elisha Whittelsey, 1966","p":["Un dibujo del pintor francés François Boucher grabado por el londinense John Ingram. Ingram se trasladó a París y, entre 1741 y 1763, hizo una serie de estampas según las chinoiseries de Boucher, la China que imaginaban los europeos. El título dice «LE JEU D'ECHETS CHINOIS», el juego del ajedrez chino.","Una mujer de peinado alto mueve una pieza en el tablero que tiene sobre las rodillas mientras un niño pequeño mira. Se considera que el juego es el xiangqi, pero las piezas reales del xiangqi son todas discos planos, y aquí hay piezas altas junto a otras pequeñas y cuadradas. La palmera y la figura sentada sobre la urna pertenecen menos a China que al país lejano con que soñaba la Europa de entonces."],"spots":[["Tablero y piezas","El tablero sobre sus rodillas, con piezas altas y cuadradas. Las piezas reales del xiangqi son discos planos."],["La mano en la pieza","Su mano derecha mueve una pieza."],["La mejilla en la mano","Con la mano izquierda en la barbilla, mira el tablero."],["El niño que mira","Un niño de pie junto al tablero sigue la partida."],["La figura de la urna","Una figura sentada con las piernas cruzadas sobre una gran urna."],["Título y nombres","«Dessiné par Fr. Boucher», «Gravé par Ingram» y el título «LE JEU D'ECHETS CHINOIS»."]]},"posada":{"title":"Juego de la Oca","artist":"José Guadalupe Posada","date":"1909","place":"México","game":"Juego de la oca","medium":"Grabado en relieve sobre zinc, impreso en papel","size":"29,3 × 39,4 cm","credit":"William McCallin McKee Memorial Endowment","p":["Una hoja para jugar hecha por el grabador mexicano Posada —famoso por sus calaveras— para el editor de la Ciudad de México Antonio Vanegas Arroyo. La cinta de abajo a la izquierda dice «JUEGO DE LA OCA», y el recorrido gira en espiral desde la casilla 1 hasta la 63, en el centro.","En el centro va impresa la EXPLICACION: si en la primera tirada salen 5 y 4 se va al 26, y con 6 y 3 al 53. Quien cae en una oca (un ave) vuelve a contar lo mismo; en la Venta (19) se esperan dos tiradas; en el Poso (31) y la Carcel (52) se queda hasta que otro lo saque; el Laberinto (42) devuelve al 39 y la Muerte (58) al principio. Hay que llegar justo al 63. Además se pagaban apuestas al caer en ciertas casillas: era también un juego de apuestas."],"spots":[["La explicación","La «EXPLICACION» del centro: qué hace cada casilla y cuándo se paga la apuesta."],["La casilla 1","La salida. Desde aquí el recorrido gira hacia el centro."],["El pozo (31)","Un pozo como una fuente. Quien cae se queda hasta que llega otro."],["La muerte (58)","La casilla de la calavera: se vuelve al principio."],["La cinta del título","«JUEGO DE LA OCA» en la cinta de abajo a la izquierda, con niños jugando debajo."],["El nombre del editor","La cinta de la diosa dice «IMPRENTA DE A. VANEGAS ARROYO», la casa que publicó muchos grabados de Posada."]]},"jintile":{"title":"Placa con mujeres jugando a un juego de tablero","artist":"Anónimo","date":"Siglo XIII","place":"China (dinastía Jin)","game":"Juego de tablero (probablemente go)","medium":"Barro cocido (relieve moldeado)","size":"Alt. 27,3 cm, anch. 24,8 cm, prof. 5,4 cm","credit":"Compra, donativos de Friends of Asian Art, 2002","p":["Una placa en relieve hecha bajo los Jin (1115–1234), la dinastía del pueblo yurchen que gobernó el norte de China. Bajo un árbol en flor, dos mujeres se sientan frente a frente en una tarima con un tablero entre ellas.","El tablero tiene una cuadrícula fina, así que probablemente juegan al go. La de la derecha se inclina y señala el tablero mientras la de la izquierda mira. Muchas tumbas de época Jin del norte de China se revestían con ladrillos en relieve con escenas de la vida diaria, y esta placa probablemente decoraba una de ellas."],"spots":[["El tablero","Un tablero de cuadrícula fina, probablemente de go."],["La mano que señala","La mujer de la derecha señala el tablero. ¿Su próxima jugada?"],["La mujer de la izquierda","Con el pelo recogido en alto, mira el tablero."],["La mujer de la derecha","Inclinada sobre el tablero."],["El árbol en flor","Ramas de un árbol en flor se extienden sobre ellas."],["La tarima","La tarima donde se sientan, con un faldón ondulado entre las patas."]]},"kyosai":{"title":"Un pedo arruina una partida de go (de un álbum de bocetos)","artist":"Kawanabe Kyōsai","date":"Mediados o finales del siglo XIX","place":"Japón (periodos Edo a Meiji)","game":"Go","medium":"Una doble página de un álbum plegable de 26 dobles hojas; tinta y color sobre papel","size":"Álbum (cerrado) 28 × 18 cm","credit":"Donación de Anne y Anthony d’Offay en honor de Evan Turner","p":["Una escena de un álbum de bocetos de Kawanabe Kyōsai (1831–1889), pintor activo desde el final del shogunato hasta la era Meiji, dibujada con trazos rápidos y libres en las páginas de un álbum plegable. Formado en la exigente técnica de la escuela Kanō, Kyōsai fue también muy querido por sus demonios, caricaturas y sátiras.","El título del museo lo dice todo: «Un pedo arruina una partida de go». A la izquierda, un hombre con gorro negro se agacha; a la derecha, el tablero sale volando, los cuencos dejan caer una lluvia de piedras y su rival cae de espaldas. Una partida seria arruinada de un solo golpe: Kyōsai recoge con su pincel veloz el viejo humor japonés del pedo, presente ya en rollos medievales."],"spots":[["El hombre del gorro negro","Agachado, con el trasero hacia fuera: ¿el causante del lío?"],["El tablero volando","El tablero cuadriculado sale despedido en diagonal."],["Cuencos y piedras","Dos cuencos se vuelcan y las piedras caen como lluvia."],["El abanico","Un abanico abierto sale volando junto al tablero."],["El rival derribado","Tumbado de espaldas, con los ojos muy abiertos."],["El trazo","Líneas de tinta enérgicas, como hechas de una vez sin boceto."]]},"yokuts":{"title":"Bandeja para juegos de azar","artist":"Tejedora yokuts (nombre desconocido)","date":"h. 1900","place":"Estados Unidos (cerca de Dunlap, California)","game":"Huuchuish (dados de cáscara de nuez)","medium":"Fibras vegetales (cestería en espiral)","size":"Alt. 5,1 cm, diám. 61 cm","credit":"Adquirida con fondos de la Sra. de Leonard S. Florsheim Jr.","p":["Muchos pueblos indígenas de California practicaban juegos de azar. Esta bandeja servía para el huuchuish, un juego de dados exclusivo de las mujeres: se lanzaban ocho dados de cáscara de nuez sobre la bandeja y se llevaba la cuenta con palitos.","El diseño circular tejido en la bandeja muestra el propio juego: los dados, los palitos de cuenta y las jugadoras (nota del museo). Es un utensilio de juego que lleva la imagen de su propio juego. En la fotografía hay dados de cáscara de nuez sobre la bandeja y alrededor."],"spots":[["Las jugadoras","Figuras que recorren el borde: quienes participan en el juego."],["Palitos de cuenta","Haces de rayitas verticales: los palitos para llevar la cuenta."],["Motivos redondos","Pequeños motivos redondos: ¿los dados?"],["Un dado de nuez","Un dado de cáscara de nuez. Se lanzaban ocho sobre la bandeja."],["La banda de triángulos","Una banda de triángulos oscuros da toda la vuelta."],["El centro","La espiral del tejido sale del centro, rodeada por un círculo de trazos."]]},"hokkei":{"title":"Ushiwakamaru vence a Benkei al sugoroku","artist":"Totoya Hokkei","date":"h. 1825","place":"Japón (periodo Edo)","game":"Ban-sugoroku","medium":"Surimono (xilografía en color, shikishiban)","size":"21,8 × 19,1 cm","credit":"Donación de Helen C. Gunsaulus","p":["Un surimono de Totoya Hokkei (1780–1850), discípulo de Hokusai. Los surimono eran estampas de encargo privado —a menudo de círculos de poesía, con sus propios versos— y se acababan con más lujo que el ukiyo-e comercial, con buen papel y pigmentos metálicos.","Ushiwakamaru, nombre de niñez del héroe Minamoto no Yoshitsune, y el gigantesco monje guerrero Benkei. Su famoso encuentro fue un duelo en el puente Gojō de Kioto, pero aquí el combate se convierte en una partida de sugoroku: el muchacho se sienta tranquilo tras el tablero y Benkei, con la alabarda a la espalda, se rasca la cabeza derrotado. Parece una recreación juguetona."],"spots":[["El tablero de sugoroku","Un tablero en forma de caja con piezas blancas y negras."],["Benkei rascándose la cabeza","Con armadura completa, el vencido se rasca la cabeza."],["Ushiwakamaru","El joven héroe, sentado tras el tablero."],["La alabarda","La hoja de la gran naginata de Benkei."],["El poema","Versos arriba a la derecha, probablemente del círculo que encargó la estampa."],["La firma","La firma de Hokkei en la cartela de abajo a la derecha."]]},"vorsterman":{"title":"Jugadores de chaquete (escena nocturna)","artist":"Lucas Emil Vorsterman, según Adam de Coster","date":"h. 1630","place":"Flandes (Amberes)","game":"Backgammon","medium":"Grabado a buril sobre papel marfil","size":"Imagen 25,5 × 34,4 cm","credit":"Colección Bernard F. Rogers","p":["Adam de Coster fue un destacado pintor de escenas nocturnas a la luz de las velas en la Amberes de hacia 1630, cuando Vorsterman, en la misma ciudad, grababa obras de contemporáneos populares. Discípulo de Rubens, Vorsterman se enemistó con su maestro y se fue a Inglaterra, tras lo cual hizo grabados más contrastados, estilizados y caravaggescos como este.","En torno a una mesa en un cuarto oscuro, unos hombres se reúnen ante un tablero de backgammon. Siguiendo el manejo de la luz de De Coster, dos velas iluminan los rostros alrededor de la mesa (nota del museo). A la derecha, un joven laudista nos mira."],"spots":[["El tablero","Un tablero de backgammon abierto como una caja sobre la mesa."],["La vela","Una vela en su candelero: su llama ilumina los rostros."],["El hombre de la pipa","Con sombrero ancho, fuma y mira la partida."],["El hombre de espaldas","Inclinado, con las manos en la mesa."],["El laudista","Un joven con un laúd que nos sonríe."],["Los nombres","«A. De Coster pi.» abajo a la izquierda, «Vorsterman» abajo a la derecha."]]},"zorn":{"title":"Jugadores de ajedrez","artist":"Anders Zorn","date":"1891","place":"Suecia","game":"Ajedrez","medium":"Aguafuerte sobre papel verjurado marfil","size":"Imagen 13,5 × 9,6 cm (plancha 13,9 × 10 cm)","credit":"Colecciones de aguafuertes de Anders Zorn de Wallace L. DeWolf y Charles Deering","p":["Un aguafuerte del artista sueco Anders Zorn (1860–1920), que alcanzó fama internacional con sus retratos al óleo y a la acuarela y dejó también una gran obra grabada. La plancha no es mayor que una mano.","Bastan líneas rápidas y oblicuas superpuestas para que surjan del cobre un cuarto oscuro y dos personas. El hombre de delante, de espaldas, se inclina sobre el tablero; la figura de enfrente baja la vista, pensando la próxima jugada. Las piezas están dibujadas con trazos finos. No consta quiénes posaron."],"spots":[["Tablero y piezas","La zona clara de abajo es el tablero; los trazos cortos verticales, las piezas."],["El hombre de delante","De espaldas, se inclina sobre el tablero."],["El rival","Con la cabeza baja, mira el tablero."],["El fondo oscuro","El fondo del cuarto, hecho de líneas verticales."],["Líneas oblicuas","La chaqueta está hecha de trazos diagonales rápidos superpuestos."],["La firma","Firmado «Zorn» a lápiz bajo la plancha."]]},"harunobu-sugoroku":{"title":"Mirando la partida (sugoroku)","artist":"Suzuki Harunobu","date":"h. 1766","place":"Japón (periodo Edo)","game":"Ban-sugoroku","medium":"Xilografía en color (chūban, surimono)","size":"28,5 × 21 cm","credit":"Colección Clarence Buckingham","p":["Suzuki Harunobu (1725?–1770) fue la figura central cuando, hacia 1765, nacieron las nishiki-e, estampas a todo color impresas con muchas planchas. Esta es un surimono de edición privada, y sus colores suaves y superpuestos muestran la novedad.","En una sala con ciruelos en flor, dos muchachas juegan ante un tablero de sugoroku en forma de caja mientras una tercera, de pie, lo observa. Fichas blancas y negras ocupan el tablero; la de la izquierda mueve una y la de la derecha alarga la mano. La puerta corredera del fondo tiene pintados una cascada y unos pinos."],"spots":[["El tablero de sugoroku","Un tablero de ban-sugoroku en forma de caja, con fichas blancas y negras."],["La muchacha de la izquierda","Con un kimono de grullas de papel, mueve una ficha."],["La muchacha de la derecha","Inclinada, alarga la mano hacia el tablero."],["La espectadora","De pie, mira la partida con un objeto de mango largo en la mano."],["El ciruelo","Un ciruelo blanco extiende sus ramas desde arriba."],["La puerta pintada","Una puerta corredera pintada con una cascada y pinos."]]},"kota":{"title":"Maharao Kishor Singh II de Kota adorando a Krishna como Brij Rajji","artist":"Anónimo","date":"h. 1825","place":"India (Rajastán, Kota)","game":"Pachisi","medium":"Témpera de goma, plata y oro sobre papel","size":"24,5 × 18,8 cm","credit":"James Albert and Mary Gardiner Ford Memorial Fund","p":["El soberano del pequeño estado principesco de Kota (r. 1819–28), vestido como sacerdote de la secta Pushti Marg, ofrece una lámpara de cinco llamas. En el pequeño santuario del altar hay imágenes de metal de Krishna flanqueado por dos consortes, un icono que solo se venera en Kota.","Del techo cuelgan muchas lámparas de vidrio, y en los escalones que suben al altar hay juguetes y juegos para entretener a Krishna y sus compañeros: elefantes de latón, vacas de plata, pelotas y un tablero de pachisi (nota del museo). La tela roja en forma de cruz es ese tablero: el pachisi ofrecido como juguete del dios."],"spots":[["El tablero de pachisi","La tela roja en cruz sobre los escalones: un tablero de pachisi."],["Elefantes","Dos elefantes de latón junto al tablero."],["Pelotas","Pelotas doradas en el escalón de arriba."],["Krishna","Las imágenes de Krishna y dos consortes en el santuario."],["El soberano y su lámpara","Vestido de sacerdote, ofrece una lámpara de cinco llamas."],["Lámparas de vidrio","Una multitud de lámparas cuelga del techo."]]},"coyote":{"title":"Juego del Coyote","artist":"Seguidor de José Guadalupe Posada","date":"Sin fecha","place":"México","game":"Coyote y gallinas (de la familia del zorro y los gansos)","medium":"Grabado en relieve sobre zinc, impreso en papel","size":"38,2 × 30,5 cm","credit":"William McCallin McKee Memorial Endowment","p":["Una hoja para jugar, impresa en relieve sobre zinc como las que Posada hacía para las imprentas populares de la Ciudad de México. Arriba se lee «JUEGO DEL COYOTE»; alrededor, coyotes asaltan el gallinero y un hombre blande un palo para ahuyentar a uno. La franja de abajo dice «Propiedad de Ildefonso T. Orellana».","La EXPLICACION impresa abajo da las reglas: juegan dos personas, una con quince fichas llamadas Gallinas y otra con una, el Coyote. Las gallinas suben y caminan hacia los lados, pero nunca retroceden; el coyote se mueve en todos sentidos y se come una gallina saltando sobre ella si detrás hay lugar vacío. Las gallinas ganan si logran encerrar al coyote. Es el mismo juego de caza que el europeo del zorro y los gansos."],"spots":[["El lugar del coyote","La cabeza del coyote en el círculo central: allí empieza el coyote."],["Los lugares de las gallinas","Círculos con gallinas: allí se colocan sus fichas."],["La explicación","La «EXPLICACION»: fichas, movimientos y cómo se gana."],["El título","«JUEGO DEL COYOTE»."],["Un coyote tras una gallina","Abajo a la izquierda, un coyote va por una gallina."],["El hombre del palo","Arriba a la derecha, un hombre alza un palo contra un coyote."]]},"mons":{"title":"Chaquete por Mons (Bergen), 1709","artist":"Pieter Nolpe (plancha y editor)","date":"Plancha 1623–53; impresión h. 1709","place":"Países Bajos (Ámsterdam)","game":"Chaquete (juego de la familia del backgammon)","medium":"Aguafuerte, buril y verso tipográfico","size":"Hoja 35,8 × 18,6 cm (plancha 12,9 × 17,5 cm)","credit":"","p":["Cuatro hombres juegan al chaquete en una mesa. Según el registro del museo, las letras A–D señalan al duque de Marlborough, al elector de Baviera, al señor de Ouwerkerk y al duque de Villeroy. Es una sátira del asedio y la toma de Mons (Bergen en neerlandés) por los aliados a los franceses en 1709, presentada como una partida en la que se juega la ciudad. En la habitación del fondo (E), el rey Felipe V de España está con una mujer.","La plancha está firmada por Pieter Nolpe como autor y editor, pero Nolpe murió a principios de la década de 1650; probablemente se reimprimió una vieja plancha del siglo XVII añadiéndole letras y un verso nuevo. El poema empieza diciendo que el juego de los grandes señores es puro tiktak y verkeer (dos juegos de tablas) y luego se burla de cada jugador."],"spots":[["El tablero","El tablero de chaquete sobre la mesa: se juega una ciudad."],["A, Marlborough","De pie, mira el tablero: el general inglés de los aliados."],["B, el elector de Baviera","Sin sombrero, hundido en su silla."],["C, Ouwerkerk","Con sombrero de plumas: el general neerlandés."],["E, la habitación del fondo","Al fondo, Felipe V con una mujer en el dormitorio."],["El verso","Verso neerlandés impreso abajo, que se burla de los jugadores A a E."]]},"stembus":{"title":"La urna: un juego de la oca político","artist":"Johan Michaël Schmidt Crans (grabador)","date":"1867","place":"Países Bajos","game":"Juego de la oca (sátira)","medium":"Litografía","size":"66 × 50 cm","credit":"","p":["Una estampa satírica en forma de juego de la oca. Se publicó con el semanario De Nederlandsche Spectator, n.º 9, del 2 de marzo de 1867, junto con una hoja suelta de reglas (registro del museo). Las casillas llevan retratos de los ministros de entonces.","Se empieza en el Binnenhof, el parlamento de La Haya, y se termina en el centro, en la casilla 64, «Insulinde» —nombre poético de las Indias Orientales Neerlandesas—, donde cuelga de la isla de Java un retrato del ministro Pieter Mijer. Mijer había pasado de ministro de Colonias a gobernador general de las Indias, y el nombramiento desató una tormenta política. La casilla de más, una sobre las 63 habituales, está ahí probablemente por el chiste final."],"spots":[["La salida","El edificio de arriba a la izquierda: se empieza en el Binnenhof de La Haya."],["El retrato de Mijer","Casilla 63: un retrato enmarcado de Pieter Mijer, colgado de la isla con cuerdas."],["Insulinde 64","La isla y el número 64 en el centro: la meta."],["La urna","«DE STEMBUS» (la urna) abajo a la derecha: la caja del título."],["Los ministros","Los rostros de los ministros de entonces asoman en las casillas."],["El gallo","Un gallo en una casilla; no se sabe de qué se burla."]]},"koorai":{"title":"Coreanos ante un juego de tablero (del Nippon de Siebold)","artist":"James Erxleben (litógrafo), según un diseño de «Toioske»","date":"1832–52","place":"Países Bajos (Leiden) / gente de Corea","game":"Juego de tablero (probablemente go)","medium":"Litografía a tono, coloreada a mano","size":"Hoja 38 × 55,5 cm","credit":"Donación de F. G. Waller","p":["Una lámina de NIPPON, la gran obra que el médico de origen alemán Philipp Franz von Siebold publicó en Leiden a partir de lo que vio en la factoría neerlandesa de Nagasaki (1823–30). Lleva «TAB. I» arriba a la derecha y «KOORAI» (Corea) abajo, con «una familia de pescadores» en neerlandés y alemán. Erxleben la dibujó en la piedra; la lámina nombra al diseñador como «Toioske».","Cuatro hombres sentados en el suelo rodean un tablero; a la izquierda una mujer lleva de la mano a un niño, a la derecha un hombre de pie sostiene un palo largo y una bolsa. Delante hay un sombrero negro de ala ancha (gat). El tablero muestra una cuadrícula y piedras redondas, así que probablemente es go (baduk en coreano), aunque el registro solo dice «un juego de tablero»."],"spots":[["El tablero","Cuadrícula con piedras redondas: probablemente una partida de go."],["El sombrero negro","Un sombrero negro de ala ancha (gat) en el suelo."],["Madre e hijo","Una mujer con un niño de la mano mira la partida."],["El hombre de pie","De pie, con un palo largo y una bolsa."],["El hombre inclinado","Con chaqueta azul, mira el tablero."],["El título","«KOORAI» (Corea), con «una familia de pescadores» en neerlandés y alemán."]]}};
